"""Research HH-weighted clipped spectral moment; approximate exponential calibration, not likelihood."""
import numpy as np
from noise_robust_spectral_weights import observed_periodogram


CAP = -np.log(.05)
CLIPPED_EXPONENTIAL_MEAN = .95


def expected_clipped_exponential(mean, cap=CAP):
    mean=np.asarray(mean,dtype=float)
    if np.min(mean)<=0 or not np.isfinite(mean).all():raise ValueError('Positive finite exponential means required')
    return -mean*np.expm1(-cap/mean)


def fit(power,low,high,hh):
    power,low,high,hh=[np.asarray(v,dtype=float) for v in (power,low,high,hh)]
    if power.ndim!=2 or power.shape[0]!=3 or low.shape!=power.shape or high.shape!=power.shape or hh.shape!=(power.shape[1],):
        raise ValueError('Three-axis powers/templates and common HH response required')
    if not all(np.isfinite(v).all() for v in (power,low,high,hh)) or min(power.min(),low.min(),high.min())<=0 or hh.min()<0 or hh.sum()<=0:
        raise ValueError('Finite positive spectral power required')
    ratio=np.log(high/low)
    if np.max(abs(ratio-np.median(ratio,axis=1,keepdims=True)))<1e-4:
        return dict(status='unidentifiable_shapes',weight=None)
    logpower=np.log(power)
    def evaluate(w):
        model=(1-w)*low+w*high
        scale=np.exp(np.median(logpower-np.log(model),axis=1))/np.log(2)
        normalized=power/(scale[:,None]*model)
        residual=(np.minimum(normalized,CAP)/CLIPPED_EXPONENTIAL_MEAN-1)
        moments=np.sum(hh*model*residual,axis=1)/np.sum(hh*model,axis=1)
        return float(np.sum(moments*moments)),scale,moments
    grid=np.linspace(0,1,129);values=[evaluate(w)[0] for w in grid]
    best=int(np.argmin(values));left,right=grid[max(0,best-1)],grid[min(128,best+1)]
    golden=(np.sqrt(5)-1)/2
    for _ in range(32):
        a,b=right-golden*(right-left),left+golden*(right-left)
        if evaluate(a)[0]<evaluate(b)[0]:right=b
        else:left=a
    candidates=[0.,1.,float(grid[best]),float((left+right)/2)]
    w=min(candidates,key=lambda w:evaluate(w)[0]);loss,scale,moments=evaluate(w)
    return dict(status='estimated_not_confidence_calibrated',weight=w,sigma=np.sqrt(scale).tolist(),
        hh_clipped_moment_residual=moments.tolist(),loss=loss,grid_weights=grid.tolist(),grid_losses=values,
        frequency_count=power.shape[1])


def estimate(planes,low,high):
    if np.min(np.std(planes,axis=(1,2)))<1e-12:return dict(status='unmeasurable_axis',weight=None)
    fy=np.fft.fftfreq(128)[:,None];fx=np.fft.fftfreq(128)[None,:]
    mask=(fy*fy+fx*fx>=.125**2)&((fy>0)|((fy==0)&(fx>0)))
    mask &= np.all((low>1e-10)&(high>1e-10)&np.isfinite(low)&np.isfinite(high),axis=0)
    if mask.sum()<512:return dict(status='insufficient_support',weight=None)
    power=observed_periodogram(planes)[:,mask]
    hh=np.broadcast_to(4*np.sin(np.pi*fy)**2*np.sin(np.pi*fx)**2,(128,128))[mask]
    return fit(np.maximum(power,np.finfo(float).tiny),low[:,mask],high[:,mask],hh)

